import 'package:material_ui/material_ui.dart';
import 'package:tldrnews_app/src/services/local_service.dart';

part 'settings_controller.g.dart';

/// User preferences, loaded from [LocalService] on creation. The fields and
/// setters come from `SettingsLogic`, generated by `settings_generator.dart`.
class SettingsController extends ChangeNotifier with SettingsLogic {
  SettingsController() {
    loadAllSettings();
  }
}
